+function postmarkPayloadForStatus({
+  deliveryId,
+  eventType,
+  messageId,
+  reason,
+  recipientEmail
+}) {
+  const payload = {
+    MessageID: randomUUID(),
+    Metadata: {
+      delivery_id: deliveryId,
+      message_id: messageId
+    },
+    Recipient: recipientEmail
+  };
