+  switch (eventType) {
+    case "delivered":
+      return { ...payload, RecordType: "Delivery" };
+
+    case "opened":
+      return { ...payload, RecordType: "Open" };
+
+    case "delayed":
+      return {
+        ...payload,
+        Details: reason,
+        RecordType: "Bounce",
+        Type: "Transient"
+      };
+
+    case "bounced":
+      return {
+        ...payload,
+        Description: reason,
+        RecordType: "Bounce",
+        Type: "HardBounce"
+      };
+
+    case "spam_complaint":
+      return {
+        ...payload,
+        Details: reason,
